func newsBadge(durum string) string {
	switch durum {
	case "ok":
		return "news-ok"
	case "hata":
		return "news-hata"
	default:
		return "news-uyari"
	}
}

func newsLabel(durum string) string {
	switch durum {
	case "ok":
		return "sorun yok"
	case "hata":
		return "hata"
	default:
		return "uyarı"
	}
}

